        let v: Vec<char> = "abcdefghijklmnopqrstuvwxyz".chars().collect();
        let res = to_uppercase(&v);
        let expected: Vec<char> = "ABCDEFGHIJKLMNOPQRSTUVWXYZ".chars().collect();
        assert_eq!(res, expected);
